head.script:
(function () {
    var errors = [];
    function render() {
        var el = document.getElementById('hht-app');
        if (!el) { return; }
        el.innerHTML = '';
        var box = document.createElement('div');
        box.setAttribute('style', 'padding:14px;font-family:monospace;font-size:12px;color:#e5e7eb;background:#111827;min-height:100vh');
        var h = document.createElement('div');
        h.setAttribute('style', 'color:#ef4444;font-weight:bold;font-size:14px;margin-bottom:10px');
        h.textContent = 'HHT shell failed to start';
        box.appendChild(h);
        var e = document.createElement('div');
        e.setAttribute('style', 'margin-bottom:10px;white-space:pre-wrap;word-break:break-all');
        e.textContent = errors.join('\n\n');
        box.appendChild(e);
        var ua = document.createElement('div');
        ua.setAttribute('style', 'color:#9ca3af;white-space:pre-wrap;word-break:break-all');
        ua.textContent = 'UA: ' + navigator.userAgent;
        box.appendChild(ua);
        el.appendChild(box);
    }
    var reportTimer = null;
    function report() {
        try {
            var xhr = new XMLHttpRequest();
            xhr.open('POST', '/hht/boot-report', true);
            xhr.setRequestHeader('Content-Type', 'application/json');
            xhr.send(JSON.stringify({
                errors: errors,
                ua: navigator.userAgent,
                url: window.location.href
            }));
        } catch (e) {
            // Reporting must never mask the failure it reports.
        }
    }
    function scheduleReport() {
        // Batch: a parse error often fires several handlers.
        if (reportTimer) { return; }
        reportTimer = setTimeout(report, 1500);
    }
    window.onerror = function (msg, src, line) {
        errors.push(String(msg) + '\n  at ' + String(src) + ':' + String(line));
        render();
        scheduleReport();
        return false;
    };
    window.addEventListener('load', function () {
        setTimeout(function () {
            if (document.querySelector('#hht-app .hht-shell')) { return; }
            if (errors.length === 0) {
                errors.push('The app did not mount within 12s and reported no error.');
            }
            render();
            scheduleReport();
        }, 12000);
    });
})();

if ('serviceWorker' in navigator) {
    window.addEventListener('load', function () {
        navigator.serviceWorker.register('/hht/sw.js', { scope: '/hht/' })
            .catch(function (e) { console.warn('SW register failed', e); });
    });
}
